const PAGE_ID = 'PASTE_YOUR_FACEBOOK_PAGE_ID_HERE';
const PAGE_ACCESS_TOKEN = 'PASTE_YOUR_FACEBOOK_PAGE_ACCESS_TOKEN_HERE';
const PUBLIC_PROPERTY_BASE_URL = 'https://your-frontend-site/properties';

const typeMap = {
  s0: 'Studio S0',
  s1: 'Appartement S1',
  s2: 'Appartement S2',
  s3: 'Appartement S3',
  s4: 'Appartement S4',
  villa: 'Villa',
};

const clean = (value) => (value ?? '').toString().trim();
const truncate = (value, max) => {
  const text = clean(value);
  return text.length > max ? `${text.slice(0, max - 3)}...` : text;
};

return items.map(({ json }) => {
  const propertyType = typeMap[json.type] || clean(json.type) || 'Bien immobilier';
  const title = clean(json.title) || 'Nouvelle propriete disponible';
  const city = clean(json.city);
  const address = clean(json.address);
  const ownerName = clean(json.ownerName);
  const price = Number(json.rent || 0);
  const deposit = Number(json.deposit || 0);
  const bedrooms = Number(json.bedrooms || 0);
  const bathrooms = Number(json.bathrooms || 0);
  const surface = Number(json.surface || 0);
  const availability = clean(json.availability);
  const propertyUrl = PUBLIC_PROPERTY_BASE_URL && !PUBLIC_PROPERTY_BASE_URL.includes('your-frontend-site')
    ? `${PUBLIC_PROPERTY_BASE_URL.replace(/\/$/, '')}/${json._id}`
    : '';

  const message = [
    `Nouveau bien disponible a ${city || 'Tunisie'}!`,
    '',
    `${propertyType}: ${title}`,
    address ? `Adresse: ${address}` : '',
    price ? `Loyer: ${price} TND / mois` : '',
    deposit ? `Caution: ${deposit} TND` : '',
    bedrooms ? `Chambres: ${bedrooms}` : '',
    bathrooms ? `Salles de bain: ${bathrooms}` : '',
    surface ? `Surface: ${surface} m2` : '',
    availability ? `Disponible a partir du: ${availability}` : '',
    ownerName ? `Proprietaire: ${ownerName}` : '',
    '',
    truncate(json.description, 220),
    '',
    propertyUrl ? `Voir le bien: ${propertyUrl}` : 'Contactez-nous en message prive pour plus de details.',
    '',
    '#immobilier #location #tunisie'
  ].filter(Boolean).join('\n');

  return {
    json: {
      ...json,
      pageId: PAGE_ID,
      pageAccessToken: PAGE_ACCESS_TOKEN,
      feedEndpoint: PAGE_ID.startsWith('PASTE_') ? '' : `https://graph.facebook.com/v25.0/${PAGE_ID}/feed`,
      postMessage: message,
    },
  };
});

return items.map((item) => ({
  json: {
    propertyId: $('Build Facebook Post').item.json._id,
    facebookPostId: item.json.id || '',
    postedAt: new Date().toISOString(),
  },
}));
